// PODATNE: parametr wstawiony DOSLOWNIE do HTML
String handleSearchVulnerable(String query) {
    return "<p>Wyniki dla: " + query + "</p>"; // query moze zawierac <script>...
}

String htmlEscape(String input) {
    return input.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                .replace("\"", "&quot;").replace("'", "&#x27;");
}

// BEZPIECZNE: query escapowane PRZED wstawieniem do HTML
String handleSearchSafe(String query) {
    return "<p>Wyniki dla: " + htmlEscape(query) + "</p>"; // <script> staje sie &lt;script&gt;
}

List<String> storedComments = new ArrayList<>();

void addComment(String comment) {
    storedComments.add(comment); // zapisujemy SUROWE dane - to jeszcze nie jest bledem samo w sobie
}

String renderCommentsVulnerable() {
    StringBuilder html = new StringBuilder();
    for (String c : storedComments) html.append("<p>").append(c).append("</p>"); // BEZ escapowania!
    return html.toString();
}

String renderCommentsSafe() {
    StringBuilder html = new StringBuilder();
    for (String c : storedComments) html.append("<p>").append(htmlEscape(c)).append("</p>"); // BEZPIECZNE
    return html.toString();
}

// ZLE: escapowanie PRZY ZAPISIE - dane w bazie sa juz "skazone" konkretnym kontekstem HTML
void addCommentWrong(String comment) {
    storedComments.add(htmlEscape(comment)); // "skazone" na stale pod HTML
}
